import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CDU0sSpB.js";const v=JSON.parse('{"title":"4.3 View, approve, and take over on the phone","description":"Keep only key actions and short-lived authority on the phone, revocable if lost.","frontmatter":{"title":"4.3 View, approve, and take over on the phone","description":"Keep only key actions and short-lived authority on the phone, revocable if lost.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-4/4-3.md","filePath":"en/delivery/stage-4/4-3.md","lastUpdated":1794017073000}'),r={name:"en/delivery/stage-4/4-3.md"};function i(s,e,l,d,h,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_4-3-view-approve-and-take-over-on-the-phone" tabindex="-1">4.3 View, approve, and take over on the phone <a class="header-anchor" href="#_4-3-view-approve-and-take-over-on-the-phone" aria-label="Permalink to &quot;4.3 View, approve, and take over on the phone&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> An installable PWA shell, offline app shell, mobile bottom navigation, and narrow-screen task and approval pages exist. The Feishu long connection can deliver task and approval messages to a phone and handle <code>/approve</code> and <code>/reject</code> text commands.</li><li><strong>Still open:</strong> Phone pairing, iOS/Android installation on real devices, system push, remote takeover, and a lost-device revocation drill are not accepted yet. This step remains a prerequisite for accepting Phase 4 as a whole.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let the user view, approve, and take over from a phone, while ensuring a lost phone can be revoked immediately and long-term primary authority is not stored on it.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Provide a phone web entry for today&#39;s tasks, items that need the user, and artifacts.</li><li>The approval page shows the real target, content, impact, and whether it can be undone; key actions require a second confirmation.</li><li>Support pause, takeover, and stop from the phone; takeover stops automatic operation immediately.</li><li>Pair with a short-lived code; the phone does not store long-term primary authority, and push content does not include sensitive text.</li><li>A lost phone can be revoked immediately; after revocation it cannot approve, take over, or view tasks.</li><li>When offline, offer read-only access and a clear state, then sync after reconnecting.</li></ol>',7)])])}const u=a(r,[["render",i]]);export{v as __pageData,u as default};
